// xanimu login panel functions (V1 static loginUi + viewName dynamic text)
function XA_toast(msg) {
  try { java.toast(String(msg)); } catch (e) {
    try { java.longToast(String(msg)); } catch (e2) {}
  }
}
function XA_refresh() {
  try { java.reLoginView(false); return; } catch (e) {}
  try { java.reLoginView(); return; } catch (e) {}
  try { java.reUiView(false); return; } catch (e) {}
  try { java.reUiView(); } catch (e) {}
}
function XA_base() {
  var b = '';
  try { b = String(source.get('xaHost') || ''); } catch (e) { b = ''; }
  if (!b || b.indexOf('http') !== 0) b = 'https://xanimu.ws';
  return b.replace(/\/+$/, '');
}
function XA_use(h) {
  var host = String(h || '').replace(/\/+$/, '');
  if (host.indexOf('http') !== 0) host = 'https://' + host;
  try { source.put('xaHost', host); } catch (e) { try { java.put('xaHost', host); } catch (e2) {} }
  XA_toast('已切换线路: ' + host);
  XA_refresh();
}
function XA_now() { return XA_base(); }
function XA_setPub(v) {
  var p = String(v || '').trim();
  if (!p) p = 'https://x99dh.com';
  if (p.indexOf('http') !== 0) p = 'https://' + p;
  try { source.put('xaPub', p); } catch (e) { try { java.put('xaPub', p); } catch (e2) {} }
  XA_toast('发布页已存: ' + p);
}
function XA_putPub() {
  var v = '';
  try { v = String(result['xaPub'] || ''); } catch (e) { v = ''; }
  if (!v || v.length < 6) v = 'https://x99dh.com';
  XA_setPub(v);
}
function XA_hexDec(h) {
  var s = '';
  for (var i = 0; i < h.length; i += 2) {
    s += String.fromCharCode(parseInt(h.substr(i, 2), 16));
  }
  return s;
}
function XA_xorBytes(a1, a2) {
  var BAOS = Packages.java.io.ByteArrayOutputStream;
  var kb = new BAOS();
  var n = a1.length < a2.length ? a1.length : a2.length;
  for (var i = 0; i < n; i++) {
    kb.write((a1[i] & 0xff) ^ (a2[i] & 0xff));
  }
  return kb.toByteArray();
}
function XA_gcm(keyBytes, ivBytes, ctBytes) {
  var cipher = Packages.javax.crypto.Cipher.getInstance('AES/GCM/NoPadding');
  var key = new Packages.javax.crypto.spec.SecretKeySpec(keyBytes, 'AES');
  var spec = new Packages.javax.crypto.spec.GCMParameterSpec(128, ivBytes);
  cipher.init(Packages.javax.crypto.Cipher.DECRYPT_MODE, key, spec);
  return java.bytesToStr(cipher.doFinal(ctBytes));
}
function XA_staticDecrypt(inner) {
  var mk = inner.match(/var k=X\(B\("([A-Za-z0-9+\/=]+)"\)\s*,\s*B\("([A-Za-z0-9+\/=]+)"\)\)/);
  var mi = inner.match(/var iv=B\("([A-Za-z0-9+\/=]+)"\)/);
  var mc = inner.match(/var ct=B\("([A-Za-z0-9+\/=]{50,})"\)/);
  if (!mk || !mi || !mc) return null;
  var k1 = java.base64DecodeToByteArray(mk[1]);
  var k2 = java.base64DecodeToByteArray(mk[2]);
  var iv = java.base64DecodeToByteArray(mi[1]);
  var ct = java.base64DecodeToByteArray(mc[1]);
  return XA_gcm(XA_xorBytes(k1, k2), iv, ct);
}
function XA_splitIvCt(all, ivLen) {
  var BAOS = Packages.java.io.ByteArrayOutputStream;
  var iv = new BAOS();
  var ct = new BAOS();
  for (var i = 0; i < all.length; i++) {
    if (i < ivLen) { iv.write(all[i] & 0xff); } else { ct.write(all[i] & 0xff); }
  }
  return { iv: iv.toByteArray(), ct: ct.toByteArray() };
}
function XA_sealedDecrypt(plain) {
  var mu = plain.match(/uk\s*=\s*C\(new Uint8Array\(\[([\d,\s]+)\]\)\s*,\s*new Uint8Array\(\[([\d,\s]+)\]\)\)/);
  var ms = plain.match(/sealed\s*=\s*\[([\s\S]*?)\];/);
  if (!mu || !ms) return null;
  var a1 = mu[1].split(',').map(function (x) { return parseInt(x.trim(), 10); });
  var a2 = mu[2].split(',').map(function (x) { return parseInt(x.trim(), 10); });
  var key = XA_xorBytes(a1, a2);
  var list = ms[1].match(/"([A-Za-z0-9+\/=]{20,})"/g) || [];
  var lines = [];
  for (var i = 0; i < list.length; i++) {
    try {
      var all = java.base64DecodeToByteArray(list[i].replace(/"/g, ''));
      var p = XA_splitIvCt(all, 12);
      lines.push(XA_gcm(key, p.iv, p.ct));
    } catch (e) {}
  }
  return lines;
}
function XA_navSites(pub) {
  var UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36';
  var body = '';
  try {
    body = String(java.ajax(pub + ',{"headers":{"User-Agent":"' + UA + '"},"retry":2}'));
  } catch (e) { body = ''; }
  if (!body || body.length < 500) return [];
  var m = body.match(/encodedData\s*=\s*'([A-Za-z0-9+\/=]+)'/);
  if (!m) return [];
  var raw = '';
  try { raw = java.base64Decode(m[1]); } catch (e2) { raw = ''; }
  if (!raw || raw.indexOf('%5B') < 0 && raw.indexOf('[{') < 0) return [];
  var json = '';
  try { json = decodeURIComponent(raw); } catch (e3) { json = raw; }
  var sites = [];
  try {
    var arr = JSON.parse(json);
    for (var si = 0; si < arr.length; si++) {
      if (arr[si] && arr[si].name && arr[si].url) {
        sites.push({ name: String(arr[si].name), url: String(arr[si].url) });
      }
    }
  } catch (e4) {
    var re = /"name"\s*:\s*"([^"]+)"[\s\S]{0,400}?"url"\s*:\s*"([^"]+)"/g;
    var mm;
    while ((mm = re.exec(json)) !== null) {
      sites.push({ name: mm[1], url: mm[2] });
    }
  }
  return sites;
}
function XA_linesFromPub(pub) {
  var hosts = [];
  var pubs = [pub, 'https://x99dh.github.io', 'https://x99dh.lat', 'https://x99dh.net'];
  for (var i = 0; i < pubs.length && hosts.length === 0; i++) {
    if (!pubs[i]) continue;
    try {
      var sites = XA_navSites(pubs[i]);
      for (var j = 0; j < sites.length; j++) {
        var u = String(sites[j].url || '');
        if (u.indexOf('xanimu') < 0) continue;
        var mh = u.match(/https?:\/\/([^\/\s]+)/);
        if (mh && hosts.indexOf(mh[1]) < 0) hosts.push(mh[1]);
      }
    } catch (e) {}
  }
  if (hosts.length === 0) { hosts = ['xanimu.ws', 'xanimu.art']; }
  return hosts;
}
function XA_fetchLines() {
  XA_toast('正在从发布页获取线路...');
  var pub = 'https://x99dh.com';
  try { pub = String(result['xaPub'] || '') || pub; } catch (e) {}
  if (pub.indexOf('http') !== 0) pub = 'https://' + pub.replace(/\/+$/, '');
  var lines = XA_linesFromPub(pub);
  for (var i = 0; i < lines.length; i++) {
    source.put('xaLine' + i, lines[i]);
  }
  source.put('xaLineN', String(lines.length));
  XA_toast('已获取 ' + lines.length + ' 条线路: ' + lines.join(', '));
  XA_refresh();
}
function XA_probe(host, cb) {
  var UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36';
  var t0 = Date.now();
  try {
    var r = java.connect(host + '/zh-CN/', JSON.stringify({ 'User-Agent': UA }), 12000);
    var code = r && r.code ? r.code() : -1;
    var ms = Date.now() - t0;
    var bodyLen = 0;
    try { bodyLen = String(r.body() || '').length; } catch (e) {}
    if (code === 200 && bodyLen > 50000) { return { ok: true, ms: ms }; }
    return { ok: false, ms: ms, why: 'HTTP' + code + '/' + bodyLen };
  } catch (e2) {
    return { ok: false, ms: Date.now() - t0, why: String(e2).substring(0, 40) };
  }
}
function XA_statusLabel() {
  var cur = XA_base();
  return '当前: ' + cur.replace('https://', '');
}
function XA_hostLabel() {
  return '主站线路(输入或点按钮切换)';
}
function XA_probeAll() {
  var hosts = [];
  try {
    var n = parseInt(String(source.get('xaLineN') || '0'), 10) || 0;
    for (var i = 0; i < n; i++) {
      var h = String(source.get('xaLine' + i) || '');
      if (h && hosts.indexOf(h) < 0) hosts.push(h);
    }
  } catch (e) {}
  if (hosts.indexOf('xanimu.ws') < 0) hosts.push('xanimu.ws');
  if (hosts.indexOf('xanimu.art') < 0) hosts.push('xanimu.art');
  XA_toast('测延时中, 共 ' + hosts.length + ' 条...');
  var best = null;
  var lines = [];
  for (var j = 0; j < hosts.length; j++) {
    var res = XA_probe('https://' + hosts[j].replace(/^https?:\/\//, ''));
    var tag = res.ok ? (res.ms + 'ms') : ('✗ ' + (res.why || '失败'));
    lines.push(hosts[j] + '=' + tag);
    if (res.ok && (!best || res.ms < best.ms)) { best = { host: hosts[j], ms: res.ms }; }
  }
  source.put('xaDelay', lines.join(' | '));
  if (best) {
    source.put('xaHost', 'https://' + best.host);
    XA_toast('最快: ' + best.host + ' ' + best.ms + 'ms 已切换');
  } else {
    XA_toast('全部线路异常: ' + lines.join(' | '));
  }
  XA_refresh();
}
function XA_lineLabel(i, def) {
  var cur = XA_base().replace('https://', '');
  var lab = '';
  try { lab = String(source.get('xaLine' + i) || ''); } catch (e) {}
  if (!lab) lab = def;
  var delay = '';
  try { delay = String(source.get('xaDelay') || ''); } catch (e2) {}
  var dd = '';
  var parts = delay.split(' | ');
  for (var k = 0; k < parts.length; k++) {
    if (parts[k].indexOf(lab) === 0) { dd = parts[k].substring(lab.length + 1); break; }
  }
  var mark = lab === cur ? '●' : '○';
  var fast = '';
  if (dd && dd.indexOf('ms') > 0) {
    var num = parseInt(dd, 10);
    if (num && num < 1500) { fast = ' ⚡'; }
  }
  return mark + ' ' + lab + (dd ? ' ' + dd : '') + fast;
}
function XA_login() { return 'ok'; }
function XA_pubLabel() {
  return '发布页网址(默认 x99dh.com)';
}
function login() { return 'ok'; }

